// Apply a resolved main-axis content size to an item and refresh measurements.
FlexItem* itemsData = allItems.data();
auto applyMainSize = [&](size_t i, int newMain) {
    if (newMain < 0) newMain = 0;
    RenderObject* c = itemsData[i].child;
    c->setOverrideSize(newMain);
    c->setNeedsLayout(true, false);
    c->layoutIfNeeded();
    itemsData[i].mainSize = (isRow ? c->width() : c->height()) + itemsData[i].mainMargin;
