    RenderObject* b = renderer("b");
    ASSERT_TRUE(a && b);
    EXPECT_NEAR(a->width(), 100, 2);
    EXPECT_NEAR(b->width(), 200, 2);
    EXPECT_NEAR(b->xPos() - a->xPos(), 100, 2);
}

