             "<div id='a'>A</div><div id='b'>B</div></div>");
    RenderObject* a = renderer("a");
    RenderObject* b = renderer("b");
    ASSERT_TRUE(a && b);
    EXPECT_NEAR(a->width(), 200, 2);
    EXPECT_NEAR(b->width(), 200, 2);
}

