    for (int r = p.row; r < p.row + p.rowSpan; r++) {
        while (r >= gridRows) {
            gridRows++;
            occupied.resize(gridRows * numCols);
            for (int c = 0; c < numCols; c++)
                occupied[(gridRows - 1) * numCols + c] = false;
        }
        for (int c = p.col; c < p.col + span && c < numCols; c++)
            occupied[r * numCols + c] = true;
    }
    if (p.col == cursorCol)
        cursorCol += span;
}

