        int itemOuterH = (align == GridAlignStretch) ? (child->height() + marginH) : p.naturalH;
        int px = cellX + child->marginLeft();
        int py = cellY + child->marginTop();
        if (justify == GridAlignEnd)
            px = cellX + cellW - itemOuterW + child->marginLeft();
