static float sideToAngle(int side1, int side2)
{
    // Single side.
    if (!side2) {
        switch (side1) {
            case CSS_VAL_TOP:    return 0.0f;
            case CSS_VAL_RIGHT:  return 90.0f;
            case CSS_VAL_BOTTOM: return 180.0f;
            case CSS_VAL_LEFT:   return 270.0f;
            default:             return 180.0f;
