// Parses an "An+B" microsyntax argument (also "odd"/"even") and tests whether
// the 1-based position matches. Whitespace is ignored. Returns false on a
// malformed argument. Supported forms: odd | even | <int> | An+B | An | n+B
// with optional signs, e.g. "2n+1", "-n+3", "3", "even".
static bool matchNth(int position, const String& argumentStr)
{
    DeprecatedString arg = argumentStr.deprecatedString().lower();
    arg.replace(" ", "");
    if (arg == "odd")
        return (position % 2) == 1;
    if (arg == "even")
        return (position % 2) == 0;

    int a = 0;
    int b = 0;
    int nPos = arg.find('n');
    if (nPos < 0) {
        // Pure integer "B".
        bool ok = false;
        b = arg.toInt(&ok);
        if (!ok)
            return false;
        return position == b;
    }

    // Coefficient before 'n' (the "A" part).
    DeprecatedString aStr = arg.left(nPos);
    if (aStr.isEmpty() || aStr == "+")
        a = 1;
    else if (aStr == "-")
        a = -1;
    else {
        bool ok = false;
        a = aStr.toInt(&ok);
        if (!ok)
            return false;
    }

    // Offset after 'n' (the "B" part, optional).
    DeprecatedString bStr = arg.mid(nPos + 1);
    if (bStr.isEmpty())
        b = 0;
    else {
        bool ok = false;
        b = bStr.toInt(&ok); // includes sign, e.g. "+1" or "-2"
        if (!ok)
            return false;
    }

    // Match if there exists a non-negative integer k with position = a*k + b.
    if (a == 0)
        return position == b;
    int diff = position - b;
    return (diff % a == 0) && (diff / a >= 0);
}

