    loadHtml("<style>.b{width:10px;} .b:first-child{width:90px;}</style>"
             "<div><div class='b' id='a'>A</div><div class='b' id='b'>B</div></div>");
    EXPECT_EQ(widthById("a"), 90);
    EXPECT_EQ(widthById("b"), 10);
}

