float PICAPI ps_set_blur(ps_context* ctx, float b)
{
    if (!picasso::is_valid_system_device()) {
        global_status = STATUS_DEVICE_ERROR;
        return 0.0f;
    }

    if (!ctx) {
        global_status = STATUS_INVALID_ARGUMENT;
        return 0.0f;
    }

    //blur range 0 ~ 1
    if (b < 0.0f) {
        b = 0.0f;
