inline void gfx_painter<Pixfmt>::apply_blur(scalar blur)
{
    if (blur > 0) {
        m_fmt.alpha(FLT_TO_SCALAR(1.0f));
        m_fmt.blend_op(comp_op_src_over);
        stack_blur<rgba8> b;
